{
  "name": "PCAN CAN总线接口适配器",
  "name_en": "PCAN CAN Bus Interface Adapter",
  "manufacturer": "PEAK-System Technik GmbH",
  "description": "PCAN 是一种用于将计算机连接到 CAN 或 CAN FD 总线网络的硬件接口设备。它常用于实验室和工程环境中，与嵌入式控制器、车辆电子节点、工业设备或自研仪器进行报文收发、总线监听、调试、参数配置和通信测试。",
  "description_en": "A PCAN device is a hardware interface that connects a computer to a CAN or CAN FD bus network. It is commonly used in laboratories and engineering environments to exchange messages with embedded controllers, vehicle electronics, industrial equipment, or custom instruments for bus monitoring, debugging, parameter configuration, and communication testing.",
  "actions": [
    {
      "action_name": "auto-Initialize",
      "description": "初始化一个 CAN 通道并设置通信速率。",
      "description_en": "Initialize a CAN channel and set the communication bitrate."
    },
    {
      "action_name": "auto-InitializeFD",
      "description": "初始化一个支持 CAN FD 的通道并设置 FD 通信速率。",
      "description_en": "Initialize a CAN FD-capable channel and set the FD communication bitrate."
    },
    {
      "action_name": "auto-Uninitialize",
      "description": "关闭并释放一个或全部已初始化的 CAN 通道。",
      "description_en": "Shut down and release one or all initialized CAN channels."
    },
    {
      "action_name": "auto-Reset",
      "description": "重置指定通道的发送和接收队列。",
      "description_en": "Reset the transmit and receive queues of the selected channel."
    },
    {
      "action_name": "auto-GetStatus",
      "description": "获取 CAN 通道的当前状态。",
      "description_en": "Get the current status of the CAN channel."
    },
    {
      "action_name": "auto-Read",
      "description": "从 CAN 通道的接收队列读取一条报文。",
      "description_en": "Read a message from the receive queue of a CAN channel."
    },
    {
      "action_name": "auto-ReadFD",
      "description": "从支持 CAN FD 的通道接收队列读取一条 FD 报文。",
      "description_en": "Read an FD message from the receive queue of a CAN FD-capable channel."
    },
    {
      "action_name": "auto-Write",
      "description": "通过 CAN 通道发送一条报文。",
      "description_en": "Transmit a message over a CAN channel."
    },
    {
      "action_name": "auto-WriteFD",
      "description": "通过支持 CAN FD 的通道发送一条 FD 报文。",
      "description_en": "Transmit an FD message over a CAN FD-capable channel."
    },
    {
      "action_name": "auto-FilterMessages",
      "description": "配置通道的接收报文过滤范围。",
      "description_en": "Configure the reception filter range for a channel."
    },
    {
      "action_name": "auto-GetValue",
      "description": "获取通道参数值。",
      "description_en": "Get a channel parameter value."
    },
    {
      "action_name": "auto-SetValue",
      "description": "设置通道参数值。",
      "description_en": "Set a channel parameter value."
    },
    {
      "action_name": "auto-GetErrorText",
      "description": "获取错误状态码的文字说明。",
      "description_en": "Get a textual description of an error status code."
    },
    {
      "action_name": "auto-LookUpChannel",
      "description": "根据给定条件查找匹配的 PCAN 通道。",
      "description_en": "Find a PCAN channel that matches the given criteria."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "CAN FD",
    "bus interface adapter",
    "message transmit and receive",
    "embedded system debugging",
    "automotive electronics",
    "industrial communication testing"
  ]
}

